import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.DfDAiEgj.js";const u=JSON.parse('{"title":"产品文档","description":"","frontmatter":{},"headers":[],"relativePath":"project/product_document.md","filePath":"project/product_document.md","lastUpdated":null}'),i={name:"project/product_document.md"};function l(n,e,c,d,s,h){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="产品文档" tabindex="-1">产品文档 <a class="header-anchor" href="#产品文档" aria-label="Permalink to &quot;产品文档&quot;">​</a></h1><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><ul><li>需求描述不清楚：前端新增页面是新开页面，还是当前页面打开。</li><li>逻辑不通：产生需求变更，不仅引起众怒，研发人员也质疑产品经理的能力。</li><li>需求遗漏：功能的排序规则不对，然后让研发修改。</li></ul><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><ol><li>灵活运用不同文档格式描述功能、业务等，而不拘泥于框架，将你的想法最大程度用文档呈现；</li><li>使你的文档逻辑有条理、框架更清晰、重点更突出，减少与开发人员的沟通成本；</li><li>利用不同的规范化文档，在接收需求、管理需求、验收需求的过程中提高工作效率。</li></ol><h2 id="产品版本v、r、m介绍" tabindex="-1">产品版本V、R、M介绍 <a class="header-anchor" href="#产品版本v、r、m介绍" aria-label="Permalink to &quot;产品版本V、R、M介绍&quot;">​</a></h2><h3 id="产品大版本-version" tabindex="-1">产品大版本（Version） <a class="header-anchor" href="#产品大版本-version" aria-label="Permalink to &quot;产品大版本（Version）&quot;">​</a></h3><p>代表公司某一产品或其系列产品，并与唯一的产品配套表对应。例如V1等。 根据市场定位或开发平台的不同，一个产品分为若干个V 级版本。每个V 级版本根据市场竞争需要、技术与成本因素等，有一个总体开发计划，按计划向市场发布若干个子版本（Release），因此V 级版本包含若干个Release版本。</p><h3 id="特性版本-release" tabindex="-1">特性版本（Release） <a class="header-anchor" href="#特性版本-release" aria-label="Permalink to &quot;特性版本（Release）&quot;">​</a></h3><p>每个Release 版本包含若干个特性，可以形成一个具体的系列产品，因此，系列产品与特性版本等同。什么特性纳入一个Release 版本，需要综合考虑市场竞争、技术与成本方面的因素，系列产品也可有自己的特性版本，系列产品可以在特性版本号上用特别的字母或数字表示。</p><h3 id="更改版本-modification" tabindex="-1">更改版本（Modification） <a class="header-anchor" href="#更改版本-modification" aria-label="Permalink to &quot;更改版本（Modification）&quot;">​</a></h3><p>如果需要在已经发布的Release 版本基础上更改（新增、改变、删除）某个特性，或者对特性下的功能、性能需求进行更改（新增、改变、删除），导致产品规格或总体方案变动，就会产生更改版本（Modification），更改版本是对发布后的Release版本的更新。</p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><p><a href="https://getquicker.net/changelog?type=Pc&amp;prev=1.10.15.0&amp;curr=1.24.34.0" target="_blank" rel="noreferrer">https://getquicker.net/changelog?type=Pc&amp;prev=1.10.15.0&amp;curr=1.24.34.0</a></p>',14)])])}const m=a(i,[["render",l]]);export{u as __pageData,m as default};
